+    fn clipboard_prefix(&self, buffer: &Buffer) -> String {
+        let Some(pending) = self.pending_clipboard.replace(None) else {
+            return String::new();
+        };
+        let text = self.selection_text(buffer, &pending.selection, pending.force_line);
+        if text.is_empty() {
+            return String::new();
+        }
+        format!("\u{1b}]52;c;{}\u{7}", base64_encode(text.as_bytes()))
+    }
+
+    fn update_last_right_cursor(&self, right_content: &str, cursor_column: Option<usize>) {
+        self.last_right_cursor
+            .set(self.right_visual_cursor_position(right_content, cursor_column));
+    }
+
+    fn right_visual_cursor_position(
+        &self,
+        right_content: &str,
+        cursor_column: Option<usize>,
+    ) -> VisualPosition {
+        let (width, height) = self.visual_pane_size(PaneFocus::Right);
+        let width = width.max(1);
+        let lines = right_content.lines().collect::<Vec<_>>();
+        let Some(line) = lines.last().copied() else {
+            return VisualPosition::origin();
+        };
+        let previous_rows = lines[..lines.len() - 1]
+            .iter()
+            .map(|line| visual_row_count(line, width as u16))
+            .sum::<usize>();
+        let line_chars = line.chars().count();
+        let cursor_chars = cursor_column.unwrap_or(line_chars).min(line_chars);
+        self.clamp_visual_position(
+            PaneFocus::Right,
+            VisualPosition {
+                row: previous_rows.saturating_add(cursor_chars / width),
+                column: cursor_chars % width,
+            },
+            width,
+            height,
+        )
+    }
+
+    fn handle_visual_key(&mut self, key: UiKey) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => {
+                self.clear_visual_selection();
+                Vec::new()
+            }
+            UiKey::Char('y') => {
+                self.yank_visual_selection(false);
+                Vec::new()
+            }
+            UiKey::Char('Y') => {
+                self.yank_visual_selection(true);
+                Vec::new()
+            }
+            UiKey::Char('v') => {
+                self.set_visual_selection_kind(VisualSelectionKind::Character);
+                Vec::new()
+            }
+            UiKey::Char('V') => {
+                self.set_visual_selection_kind(VisualSelectionKind::Line);
+                Vec::new()
+            }
+            UiKey::Char(CTRL_V_KEY) => {
+                self.set_visual_selection_kind(VisualSelectionKind::Block);
+                Vec::new()
+            }
+            UiKey::Char('h') | UiKey::Left => {
+                self.move_visual_cursor(0, -1);
+                Vec::new()
+            }
+            UiKey::Char('j') | UiKey::Down => {
+                self.move_visual_cursor(1, 0);
+                Vec::new()
+            }
+            UiKey::Char('k') | UiKey::Up => {
+                self.move_visual_cursor(-1, 0);
+                Vec::new()
+            }
+            UiKey::Char('l') | UiKey::Right => {
+                self.move_visual_cursor(0, 1);
+                Vec::new()
+            }
+            _ => Vec::new(),
+        }
+    }
+
+    fn start_visual_selection(&mut self, kind: VisualSelectionKind) {
+        let pane = if self.focus == PaneFocus::Left && !self.left_visible {
+            PaneFocus::Right
+        } else {
+            self.focus
+        };
+        let position = self.current_visual_position(pane);
+        self.pending = None;
+        self.mode = UiMode::Command;
+        self.visual_selection = Some(VisualSelection {
+            pane,
+            kind,
+            anchor: position,
+            cursor: position,
+        });
+    }
+
+    fn set_visual_selection_kind(&mut self, kind: VisualSelectionKind) {
+        if let Some(mut selection) = self.visual_selection {
+            selection.kind = kind;
+            self.visual_selection = Some(selection);
+        }
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize) {
+        let Some(mut selection) = self.visual_selection else {
+            return;
+        };
+        let (width, height) = self.visual_pane_size(selection.pane);
+        selection.cursor = self.clamp_visual_position(
+            selection.pane,
+            VisualPosition {
+                row: add_signed(selection.cursor.row, row_delta),
+                column: add_signed(selection.cursor.column, column_delta),
+            },
+            width,
+            height,
+        );
+        self.visual_selection = Some(selection);
+    }
+
+    fn yank_visual_selection(&mut self, force_line: bool) {
+        let Some(selection) = self.visual_selection.take() else {
+            return;
+        };
+        self.pending_clipboard.set(Some(PendingClipboardSelection {
+            selection,
+            force_line,
+        }));
+        let message = if force_line {
+            "copied selected lines"
+        } else {
+            "copied selection"
+        };
+        self.show_status_notice(message, Duration::from_secs(STATUS_NOTICE_SECONDS));
+    }
+
+    fn yank_current_line(&mut self) {
+        let pane = if self.focus == PaneFocus::Left && !self.left_visible {
+            PaneFocus::Right
+        } else {
+            self.focus
+        };
+        let position = self.current_visual_position(pane);
+        self.pending_clipboard.set(Some(PendingClipboardSelection {
+            selection: VisualSelection {
+                pane,
+                kind: VisualSelectionKind::Line,
+                anchor: position,
+                cursor: position,
+            },
+            force_line: true,
+        }));
+        self.show_status_notice("copied line", Duration::from_secs(STATUS_NOTICE_SECONDS));
+    }
+
+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+    }
+
+    fn current_visual_position(&self, pane: PaneFocus) -> VisualPosition {
+        let (width, height) = self.visual_pane_size(pane);
+        let position = match pane {
+            PaneFocus::Left => VisualPosition {
+                row: self.control_selected_content_row(),
+                column: 0,
+            },
+            PaneFocus::Right => self.last_right_cursor.get(),
+        };
+        self.clamp_visual_position(pane, position, width, height)
+    }
+
+    fn clamp_visual_position(
+        &self,
+        _pane: PaneFocus,
+        position: VisualPosition,
+        width: usize,
+        height: usize,
+    ) -> VisualPosition {
+        VisualPosition {
+            row: position.row.min(height.saturating_sub(1)),
+            column: position.column.min(width.saturating_sub(1)),
+        }
+    }
+
+    fn visual_pane_size(&self, pane: PaneFocus) -> (usize, usize) {
+        self.visual_pane_inner_rect(pane)
+            .map(|rect| (usize::from(rect.width), usize::from(rect.height)))
+            .unwrap_or((1, 1))
+    }
+
+    fn visual_pane_inner_rect(&self, pane: PaneFocus) -> Option<Rect> {
+        let layout = self.layout();
+        let body_height = self.height.saturating_sub(1);
+        if body_height <= 2 {
+            return None;
+        }
+        match pane {
+            PaneFocus::Left => {
+                if !self.left_visible || layout.left_width <= 2 {
+                    return None;
+                }
+                Some(Rect::new(1, 1, layout.left_width - 2, body_height - 2))
+            }
+            PaneFocus::Right => {
+                if layout.right_width <= 2 {
+                    return None;
+                }
+                let pane_x = if self.left_visible {
+                    layout.left_width
+                } else {
+                    0
+                };
+                Some(Rect::new(pane_x + 1, 1, layout.right_width - 2, body_height - 2))
+            }
+        }
+    }
+
+    fn visual_cursor_screen_position(&self, selection: VisualSelection) -> (u16, u16) {
+        let Some(rect) = self.visual_pane_inner_rect(selection.pane) else {
+            return (1, 1);
+        };
+        (
+            rect.y.saturating_add(selection.cursor.row.min(usize::from(rect.height - 1)) as u16),
+            rect.x.saturating_add(
+                selection
+                    .cursor
+                    .column
+                    .min(usize::from(rect.width - 1)) as u16,
+            ),
+        )
+    }
+
+    fn apply_visual_selection(&self, buffer: &mut Buffer) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        self.apply_selection_to_buffer(buffer, &selection, false);
+    }
+
+    fn apply_selection_to_buffer(
+        &self,
+        buffer: &mut Buffer,
+        selection: &VisualSelection,
+        force_line: bool,
+    ) {
+        let Some(rect) = self.visual_pane_inner_rect(selection.pane) else {
+            return;
+        };
+        let width = usize::from(rect.width);
+        for row in 0..usize::from(rect.height) {
+            let Some(columns) = selection_column_range(selection, row, width, force_line) else {
+                continue;
+            };
+            for column in columns {
+                let x = rect.x.saturating_add(column as u16);
+                let y = rect.y.saturating_add(row as u16);
+                buffer.get_mut(x, y).modifier.insert(Modifier::REVERSED);
+            }
+        }
+    }
+
+    fn selection_text(
+        &self,
+        buffer: &Buffer,
+        selection: &VisualSelection,
+        force_line: bool,
+    ) -> String {
+        let Some(rect) = self.visual_pane_inner_rect(selection.pane) else {
+            return String::new();
+        };
+        let width = usize::from(rect.width);
+        let mut lines = Vec::new();
+        for row in 0..usize::from(rect.height) {
+            let Some(columns) = selection_column_range(selection, row, width, force_line) else {
+                continue;
+            };
+            let mut line = String::new();
+            for column in columns {
+                let x = rect.x.saturating_add(column as u16);
+                let y = rect.y.saturating_add(row as u16);
+                line.push_str(&buffer.get(x, y).symbol);
+            }
+            lines.push(line.trim_end().to_string());
+        }
+        while lines.last().is_some_and(|line| line.is_empty()) {
+            lines.pop();
+        }
+        lines.join("\n")
+    }
